// ─── File: NonSealedDemo.java ───
// Single runnable file with multiple top-level package-private classes.
package com.bank.nonsealed;

import java.math.BigDecimal;
import java.util.List;
import java.util.logging.*;

public class NonSealedDemo {
    private static final Logger log = Logger.getLogger(NonSealedDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        AccountHandler handler = new AccountHandler();

        // WalletProduct is NOT listed in any permits clause, yet it is a valid
        // Account because it extends the NON-SEALED PartnerProduct branch.
        List<Account> accounts = List.of(
            new SavingsAccount("SAV2001", new BigDecimal("1000000")),
            new CurrentAccount("CUR3001", new BigDecimal("250000")),
            new WalletProduct("WAL9001", new BigDecimal("15000"), "PayFast"));

        for (Account a : accounts) {
            log.info(() -> handler.describe(a));
        }

        Account unlisted = new WalletProduct("WAL9002", new BigDecimal("3000"), "QuickPay");
        log.info(() -> "Unlisted WalletProduct is an Account? " + (unlisted instanceof Account));
        log.info(() -> "Unlisted WalletProduct is a PartnerProduct? "
                + (unlisted instanceof PartnerProduct));
    }
}

// ─── Would be in model/Account.java ───
// Sealing restricts DIRECT implementors to these three only.
sealed interface Account permits SavingsAccount, CurrentAccount, PartnerProduct {
    String id();
    BigDecimal balance();
}

// ─── Would be in model/SavingsAccount.java ───
final class SavingsAccount implements Account {
    private final String id; private final BigDecimal balance;
    SavingsAccount(String id, BigDecimal balance) { this.id = id; this.balance = balance; }
    public String id() { return id; } public BigDecimal balance() { return balance; }
}

// ─── Would be in model/CurrentAccount.java ───
final class CurrentAccount implements Account {
    private final String id; private final BigDecimal balance;
    CurrentAccount(String id, BigDecimal balance) { this.id = id; this.balance = balance; }
    public String id() { return id; } public BigDecimal balance() { return balance; }
}

// ─── Would be in model/PartnerProduct.java ───
// NON-SEALED: deliberately reopens this branch. ANY class may extend it,
// and such classes need NOT appear in any permits clause.
non-sealed class PartnerProduct implements Account {
    private final String id; private final BigDecimal balance;
    PartnerProduct(String id, BigDecimal balance) { this.id = id; this.balance = balance; }
    public String id() { return id; } public BigDecimal balance() { return balance; }
    String partnerName() { return "GENERIC"; }
}

// ─── Would be in model/WalletProduct.java ───
// UNLISTED class: not in any permits clause, yet legal because it extends the
// non-sealed PartnerProduct. Transitively it IS an Account.
class WalletProduct extends PartnerProduct {
    private final String partner;
    WalletProduct(String id, BigDecimal balance, String partner) { super(id, balance); this.partner = partner; }
    @Override String partnerName() { return partner; }
}

// ─── Would be in service/AccountHandler.java ───
class AccountHandler {
    // Switch stays exhaustive at the PERMITTED level: matching PartnerProduct
    // covers it AND any unlisted subclass beneath it (e.g. WalletProduct).
    String describe(Account a) {
        return switch (a) {
            case SavingsAccount s -> "SAVINGS " + s.id() + " Rs." + s.balance();
            case CurrentAccount c -> "CURRENT " + c.id() + " Rs." + c.balance();
            case PartnerProduct p -> "PARTNER(" + p.partnerName() + ") " + p.id() + " Rs." + p.balance();
        };
    }
}

// ─── Would be in util/BankLogFormatter.java ───
class BankLogFormatter extends java.util.logging.Formatter {
    @Override public String format(java.util.logging.LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
